import { QueryClientProvider } from "@tanstack/react-query";
import Link from "next/link";
import { useParams, useRouter } from "next/navigation";
import { useTheme } from "next-themes";
import type { ReactNode } from "react";
// import { apiKeyPlugin } from "@/src/lib/auth/api-key-plugin";
import { adminPlugin } from "@/lib/auth/admin-plugin";
// import { deleteUserPlugin } from "@/src/lib/auth/delete-user-plugin";
// import { magicLinkPlugin } from "@/src/lib/auth/magic-link-plugin";
// import { multiSessionPlugin } from "@/src/lib/auth/multi-session-plugin";
// import { organizationPlugin } from "@/src/lib/auth/organization-plugin";
