            // deleteUserPlugin(),
            // organizationPlugin({
            // slugPrefix: "@",
            // slug,
            // }),
          ]
        }
        Link={Link}
      >
        {children}

        <Toaster />
      </AuthProvider>
    </QueryClientProvider>
  );
}

